const previewImage = "data:image/jpeg;base64,";
function useCopy() { const { lang } = useI18n(); return copy[lang] ?? copy.pl; }

export function SafetyCourseCard({ course }: { course: Course }) {
  const c = useCopy();
  return <article className="card-elevated card-raise flex h-full flex-col overflow-hidden rounded-xl border border-gold/30">
    <img src={previewImage} alt="" loading="lazy" className="aspect-[3/2] w-full object-cover" />
    <div className="flex flex-1 flex-col gap-3 p-5">
      <p className="text-xs font-semibold tracking-widest text-gold">{c.badge}</p>
      <h3 className="text-xl font-bold text-gold">{c.title}</h3>
      <p className="text-sm text-muted-foreground">{c.description}</p>
      <p className="text-sm font-medium">{c.form}</p>
      <p className="text-sm text-muted-foreground">{c.modules} · {c.duration}</p>
      <p className="text-xs text-muted-foreground">{c.materials}</p>
      <div className="mt-auto flex items-end justify-between gap-3 pt-4">
        <div><p className="text-2xl font-bold">{(course.price_cents / 100).toFixed(0)} €</p><p className="text-xs text-muted-foreground">{c.status}</p></div>
        <Link to="/kurs/$slug" params={{ slug: course.slug }} className="rounded-md bg-accent px-4 py-2 text-sm font-semibold text-accent-foreground">{c.details}</Link>
      </div>
    </div>
  </article>;
}

